import{_ as t,o,c as s,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-14-update-workspace-profile/report3_spec.md","filePath":"feature/agency-workspace/3-4-14-update-workspace-profile/report3_spec.md"}'),i={name:"feature/agency-workspace/3-4-14-update-workspace-profile/report3_spec.md"};function n(a,e,l,p,c,d){return o(),s("div",null,[...e[0]||(e[0]=[r("<p><strong>3.4.14 Update Workspace Profile</strong></p><p><strong>Function Trigger</strong></p><p>Begins when the MANAGER of a Workspace submits changes to the Workspace profile or settings.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The MANAGER of the Workspace, and only that role.</li><li><strong>Purpose</strong>: Lets the Workspace MANAGER keep the Workspace&#39;s details and settings accurate with day-to-day operations.</li><li><strong>Interface</strong>: Workspace settings screen - the same page that displays the profile (FR 3.4.13); the edit form and logo control appear on it directly.</li><li><strong>Data Processing</strong>: The system loads the Workspace, merges the supplied fields into the record and settings, and returns the updated Workspace profile.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Settings Screen, edit section:</p><ul><li>Logo block, shown only when the caller can manage the Workspace; client-side accepts image/jpeg, image/png, image/webp and rejects files over 5 MB before calling the upload endpoint.</li><li>Form pre-filled with the current name, timezone, default platforms, report frequency, industry, company size, website, phone, and location.</li><li>A &quot;Save&quot; action; on success a confirmation toast is shown and the form keeps the newly entered values.</li><li>Out of scope for this FR but on the same screen: a &quot;Save as Template&quot; dialog (FR 3.4.17) and a Danger Zone delete-Workspace block (FR 3.4.15).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: name, timezone, defaultPlatforms, reportFrequency (WEEKLY / MONTHLY), industry, companySize, website, phone, location. For the logo control: the uploaded image file.</li><li><strong>System data</strong>: the existing Workspace record and its stored settings; the caller&#39;s role in that Workspace; the stored URL of the uploaded logo.</li><li><strong>Output</strong>: the updated Workspace profile - id, name, agencyId, slug, ownerId, settings, industry, companySize, website, phone, location, description, branding fields, social links, isActive, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-25</strong>: Workspace settings and logo can only be updated by MANAGER; all settings fields are optional (partial update).</li><li><strong>BR-35</strong>: The role check re-reads the caller&#39;s role from the database at request time and runs before the not-found lookup. SystemRole.ADMIN bypasses the check.</li><li>The Workspace must exist -&gt; otherwise 404 WORKSPACE_NOT_FOUND.</li><li><strong>BR-25</strong>: Fields not supplied in the request keep their current values; the stored settings are merged rather than replaced.</li><li>A failure while reading the uploaded logo file -&gt; 400 FILE_READ_ERROR.</li><li>The logo is uploaded through its own dedicated action, not through the profile settings update.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The caller must hold the MANAGER role in that Workspace; otherwise 403 FORBIDDEN.</li><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND.</li><li>industry must be a valid WorkspaceIndustry value; companySize must be a valid CompanySize value. Empty required field -&gt; Display: <strong>MSG02</strong>. Exceeding max length -&gt; Display: <strong>MSG03</strong>.</li><li>An unreadable logo file -&gt; 400 FILE_READ_ERROR. The frontend rejects non-image files and files over 5 MB before the request is sent.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>MANAGER opens Workspace settings and edits the name, timezone, default platforms, report frequency, industry, company size, website, phone, or location.</li><li>System confirms the caller holds the MANAGER role in that Workspace; otherwise the request fails with 403 FORBIDDEN.</li><li>System loads the Workspace; if it does not exist the request fails with 404 WORKSPACE_NOT_FOUND.</li><li>System applies the supplied fields and merges the new timezone / default platforms into the stored settings, keeping previous values for fields left out.</li><li>System returns the updated Workspace profile; the screen shows a success confirmation, toast <strong>MSG32</strong>. The separate logo upload action, on success, shows toast <strong>MSG94</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Caller is not the MANAGER of that Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 2.a2: The caller stays on the same screen with the edit controls hidden.</li><li>3.a1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 3.a2: The MANAGER returns to the Workspace list.</li><li>3.b1: Logo upload file cannot be read -&gt; 400 FILE_READ_ERROR. 3.b2: The user retries with another file.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Workspace record and its settings carry the new values; fields not supplied are unchanged.</li><li>When a logo was uploaded, the Workspace holds the new logo location.</li></ul>",14)])])}const h=t(i,[["render",n]]);export{u as __pageData,h as default};
